# -*- coding: utf-8 -*-
# AUTO-GENERATED by parse_phase3.py, Phase-3 glossary terms.
GLOSSARY_ADD = [
    {"term": "Volumetric water content (VWC)", "defn": "Volumetric water content (VWC) is the fraction of the total volume of the media that is liquid water, in m3/m3. A value of 0.34 shows that 34% of the volume of the pot is water. It is the primary number for irrigation steering.", "tags": ['reference']},
    {"term": "Permittivity (dielectric constant)", "defn": "Permittivity (dielectric constant) shows how strong the effect of an electric field is on a material. The value is very high for water (approximately 80), approximately 3 to 5 for dry substrate, and approximately 1 for air. Thus a capacitance sensor can calculate the water content from this difference.", "tags": ['reference']},
    {"term": "Volume of influence", "defn": "The volume of influence is the part of the media that a probe senses. For the TEROS-12, it is approximately 1010 mL. This volume is large for a dielectric probe, but it is only a local sample of one position.", "tags": ['reference']},
    {"term": "Resolution vs accuracy", "defn": "Resolution is the smallest change that a sensor can show (0.001 m3/m3 here). Accuracy is how close the value is to the correct value (+/-0.03 with the general equation, +/-0.01-0.02 after calibration). The two are not the same.", "tags": ['reference']},
    {"term": "Bulk EC", "defn": "Bulk EC is the electrical conductivity of the mixture of the wet media (solids, water and air). The probe measures it directly in the range of 0-20000 microS/cm.", "tags": ['reference']},
    {"term": "Hilhorst model", "defn": "The Hilhorst model is a method from the year 2000. It gives an estimate of the pore-water EC from the bulk EC, the VWC and the temperature. You can use it, but its sensitivity is approximately +/-20%, and it is not correct when the VWC is less than 0.10 m3/m3.", "tags": ['reference']},
    {"term": "DUL (drained upper limit) / container capacity", "defn": "DUL (drained upper limit), or container capacity, is the quantity of water that a container holds after free drainage stops. It is a value that you find for each pot, and it is not a constant value for the substrate. It changes slowly when the roots become larger.", "tags": ['reference']},
    {"term": "Specific yield (S)", "defn": "Specific yield (S) is the change in VWC for each mL of water that you supply (formula dVWC/delivered_mL). When S becomes almost zero, it is a possible sign that the pot is full, but it is only a possible sign.", "tags": ['reference']},
    {"term": "Substrate-specific calibration", "defn": "Substrate-specific calibration is the replacement of the general equation of the probe with an equation that you calculate for your media. The accuracy of the VWC becomes better, from +/-0.03 to +/-0.01-0.02 m3/m3. It is mandatory for accurate steering.", "tags": ['reference']},
    {"term": "SDI-12", "defn": "SDI-12 is the digital serial protocol that the TEROS-12 uses to send the VWC, EC and temperature. A value that does not change, that is NaN, or that is at a limit of its range is a hardware fault and not data.", "tags": ['reference']},
    {"term": "Safe headroom", "defn": "Safe headroom is a lower-confidence-bound estimate of the quantity of water that you can add before the pot is full. It is the only headroom number that gives approval for a shot.", "tags": ['reference']},
    {"term": "Representativeness fault", "defn": "A representativeness fault occurs when the probe works correctly, but its local volume of 1010 mL is not typical of the zone (channeling, air gap, moved probe). The reading is correct for the local volume, but it gives incorrect information about the zone.", "tags": ['reference']},
    {"term": "VRWE (Virtual Root-Zone Water Estimator)", "defn": "VRWE (Virtual Root-Zone Water Estimator) is software that calculates an estimate of the water in the root zone of a plant. It uses some signals together, and then it selects the irrigation. It does not use only one moisture probe.", "tags": ['precision']},
    {"term": "Water balance / bank account", "defn": "The water balance is the water that you supply (irrigation), minus the water that the plant uses, minus the runoff. You calculate it continuously. It is equal to the estimate of the water in the pot.", "tags": ['precision']},
    {"term": "Runoff / drain", "defn": "Runoff (drain) is the water that flows out of the bottom of the pot.", "tags": ['precision']},
    {"term": "Full pot (DUL, drained upper limit)", "defn": "The full pot (DUL, drained upper limit) is the maximum quantity of water that a pot can hold after drainage.", "tags": ['precision']},
    {"term": "Channeling (preferential flow)", "defn": "Channeling (preferential flow) is water that flows straight down through the substrate. It does not touch the roots, and frequently it does not touch the sensor.", "tags": ['precision']},
    {"term": "Confidence", "defn": "Confidence is the value that the system gives to show how accurate its estimate is at this time. When the confidence is high, the system can apply water. When the confidence is low, the system must be careful.", "tags": ['precision']},
    {"term": "Shared-drain (sump) puzzle", "defn": "The shared-drain puzzle (sump puzzle) occurs when the water from some rooms, from the AC and from the dehumidifier goes into one bucket. Thus you cannot know which source caused a flush.", "tags": ['precision']},
    {"term": "Background drip baseline", "defn": "The background drip baseline is the stable drip of the AC and the dehumidifier that the system finds at night. Then the system can subtract it from the total drain readings.", "tags": ['precision']},
    {"term": "Signal", "defn": "A signal is a change in the plant or in the root zone that is important for your control. A signal can be a trend that continues, a step change that has a known cause, or a rhythm that occurs each day.", "tags": ['reference']},
    {"term": "Noise", "defn": "Noise is a random change in a measurement that does not show a change in the plant. The examples are a spike in one reading, jitter of high frequency, and transients from doors, the movement of personnel and irrigation events.", "tags": ['reference']},
    {"term": "Signal-to-noise ratio (SNR)", "defn": "The signal-to-noise ratio (SNR) is the strength of the signal compared with the strength of all other changes in the data. When the SNR is high, the data are stable and easy to read. When the SNR is low, the data have many changes, and the control adjusts for each change.", "tags": ['reference']},
    {"term": "Drift", "defn": "Drift is a slow sensor error that is always in the same direction, and it shows a trend that does not occur in the plant. It is the dangerous type of noise. Only calibration and a check with other data can remove it.", "tags": ['reference']},
    {"term": "Aliasing", "defn": "Aliasing is an effect in data that occurs when the sampling is too slow. The slow sampling changes a fast cycle into a slow cycle that does not occur in the plant.", "tags": ['reference']},
    {"term": "Nyquist rule", "defn": "The Nyquist rule is that the sampling rate must be a minimum of two times the frequency of the fastest cycle that you must find. If the rate is lower, you will read the cycle incorrectly, or the data will show a cycle that does not occur.", "tags": ['reference']},
    {"term": "Moving (rolling) average", "defn": "A moving average (rolling average) is the average of the last N readings. You calculate it again when you get each new reading. It decreases random variation, but it adds a small lag.", "tags": ['reference']},
    {"term": "EWMA", "defn": "EWMA is the exponentially-weighted moving average. It is a rolling average that gives more weight to the newest readings. Thus it has less lag for the same smoothing.", "tags": ['reference']},
    {"term": "Median filter", "defn": "A median filter uses the middle value of the last N readings. It is very good for the removal of a spike in one reading. It does not change a step change that occurs in the plant.", "tags": ['reference']},
    {"term": "Statistical process control (SPC)", "defn": "Statistical process control (SPC) is a method from manufacturing. It uses the recorded data of the operation to find if a change is only usual noise, or a signal for a correction.", "tags": ['reference']},
    {"term": "Common-cause variation", "defn": "Common-cause variation is the usual small random change of a stable operation. It stays in the control limits. You must not adjust the operation for this variation.", "tags": ['reference']},
    {"term": "Special-cause variation", "defn": "Special-cause variation is a change that has a cause that you can find. Something in the operation changes, and the variation is out of the control limits. You must do an investigation.", "tags": ['reference']},
    {"term": "Control limits", "defn": "Control limits are limits that you calculate from the data that you recorded for the operation (typically the mean ± 3 standard deviations). They divide the usual variation from the unusual variation.", "tags": ['reference']},
    {"term": "Tampering", "defn": "Tampering is an adjustment of the operation for common-cause variation, as if this variation is special-cause variation. Deming showed that tampering increases the variation of the operation.", "tags": ['reference']},
    {"term": "Coefficient of variation (CV)", "defn": "The coefficient of variation (CV) shows how large the variation is, in relation to the average. For a batch of plants, the CV measures the noise (the differences between the plants) in your crop.", "tags": ['reference']},
    {"term": "Dead-band", "defn": "A dead-band is the tolerance range in which a controller does not make a correction. If the dead-band is too small, the equipment makes too many adjustments (hunting).", "tags": ['reference']},
    {"term": "Hunting", "defn": "Hunting is an oscillation in a feedback loop. The loop makes corrections that are too large, in one direction and then in the other direction, and it does not become stable. The cause is frequently noise in the input or a tuning that is too sensitive.", "tags": ['reference']},
    {"term": "Closed loop", "defn": "A closed loop is a control system in which the result goes back to cause the next step. The steps are: measure, select, adjust, and then measure the effect of the adjustment. The system does these steps again, continuously.", "tags": ['reference']},
    {"term": "Lever (actuator)", "defn": "A lever (actuator) is each control that you can change in the room. The examples are the light intensity, the cooling setpoint, the irrigation shot and the dose of CO2. The paper counts eleven primary groups of levers.", "tags": ['reference']},
    {"term": "Coupled system", "defn": "A coupled system is a system in which a change to one control changes some other controls at the same time. Thus no lever operates independently.", "tags": ['reference']},
    {"term": "Setpoint", "defn": "A setpoint is the specified number that you give to the equipment. The equipment tries to get this number (for example, 24C for the temperature of the room).", "tags": ['reference']},
    {"term": "Target", "defn": "A target is the result that you want to get (for example, a good transpiration rate). A setpoint is only an indicator of the target.", "tags": ['reference']},
    {"term": "Plant state", "defn": "The plant state is the condition of the plant that the system calculates (for example, on-track, stress, or steering generative). The system uses many signals together, and not one instrument.", "tags": ['reference']},
    {"term": "Common cause vs special cause", "defn": "Common-cause variation is the usual small random change, and you do not adjust the operation for it. Special-cause variation is an unusual change, for example a point that is out of a limit or a sequence of points that is not random. An investigation is necessary for it.", "tags": ['reference']},
    {"term": "Sampling cadence", "defn": "Sampling cadence is how frequently you record a measurement. It must agree with the biology. It must be sufficiently fast to find the changes in the plant, and sufficiently slow to prevent a record of noise that has no value.", "tags": ['reference']},
    {"term": "Learned envelope", "defn": "A learned envelope is the range of values that shows a plant in good condition, for the cultivar, the growth stage and the photoperiod. The system uses it as an alternative to one constant threshold.", "tags": ['reference']},
    {"term": "Advisory / prescription", "defn": "An advisory (prescription) is an output that gives the task, the setpoint, the time limit and the result that will occur. It tells you: 'do this, by this time, or this result will occur'. It is not only an alarm.", "tags": ['reference']},
    {"term": "Oscillation", "defn": "In oscillation, a loop makes corrections that are too large, in one direction and then in the other direction. The loop does not become stable. Usually the loop operates too quickly, too strongly, or makes corrections for noise.", "tags": ['reference']},
    {"term": "Transpiration", "defn": "In transpiration, a plant pulls water up and releases it as vapor through its leaves. Transpiration is a primary cause that connects water, heat and humidity.", "tags": ['reference']},
    {"term": "VPD (vapor pressure deficit)", "defn": "VPD shows how strongly the air pulls moisture from the plant, and it causes transpiration. You measure it in kPa (for example, 1.4-1.6). The correct value is different for each growth stage.", "tags": ['precision']},
    {"term": "Inference layer", "defn": "The inference layer is the part of the system that calculates estimates of values that you cannot measure directly (plant stress, transpiration and vigor). It uses values that you can measure.", "tags": ['precision']},
    {"term": "Baseline / trajectory", "defn": "The baseline (trajectory) is the learned envelope for a specified cultivar, growth stage and photoperiod phase. The system calculates it from the data of your previous crops.", "tags": ['precision']},
    {"term": "Leading vs lagging indicator", "defn": "A leading indicator is a sign that occurs before the damage, and it tells you about the problem. A lagging indicator is a symptom that shows that the damage occurred.", "tags": ['precision']},
    {"term": "PPFD / DLI", "defn": "PPFD is the intensity of light at one time. DLI is the total quantity of light that the plants receive in one day. The system monitors the DLI up to this time, and not only the PPFD at one time.", "tags": ['precision']},
    {"term": "Transpiration proxy", "defn": "A transpiration proxy is an estimate of the rate at which the plant transpires. The system calculates it from the VPD, the light and the change in the water content of the substrate.", "tags": ['precision']},
    {"term": "Named condition", "defn": "A named condition is a short diagnosis that a person can read (for example, 'salt accumulation pattern'). It has a confidence value and an evidence chain. It replaces a large quantity of numbers.", "tags": ['precision']},
    {"term": "Calm dashboard", "defn": "A calm dashboard is a screen that shows exceptions. Usually the screen gives no information. It tells you only when there is important information.", "tags": ['precision']},
    {"term": "Closed loop (gated)", "defn": "In a gated closed loop, the system does automatically only the tasks that have a low risk and a specified license. A person must give approval for each task that is permanent or has a high cost.", "tags": ['precision']},
    {"term": "Shot", "defn": "A shot is one small irrigation event. The size of a shot is a percentage of the water capacity of the pot (for example, a 5% shot).", "tags": ['precision']},
    {"term": "Coco coir", "defn": "Coco coir is a substrate of coconut husk that you use as an alternative to soil. Water flows out of it quickly, and it changes quickly when you apply water.", "tags": ['precision']},
    {"term": "Field capacity", "defn": "Field capacity is the maximum VWC that the medium can hold before water flows out. The default maximum is 70%.", "tags": ['precision']},
    {"term": "P0-P3 phases", "defn": "The P0-P3 phases are the four irrigation stages of each day. P0 is the morning dryback, P1 is the ramp-up, P2 is the maintenance, and P3 is the stage before lights-off (emergency only).", "tags": ['precision']},
    {"term": "Crop Steering AI (CS)", "defn": "Crop Steering AI (CS) is an irrigation system with 4 phases. It uses sensor data, and it has control for each zone, EC logic and ML prediction. It is the irrigation controller that operates at this time.", "tags": ['precision']},
    {"term": "Zone / table", "defn": "A zone (table) is one of the six grow tables that you control independently. Each table has a valve, a probe and a phase state.", "tags": ['precision']},
    {"term": "Substrate probe", "defn": "A substrate probe is a sensor in the medium (here GroundWork). It sends the VWC and the EC for a zone.", "tags": ['precision']},
    {"term": "ESPHome", "defn": "ESPHome is the firmware platform that operates the hardware sensors and some switches. It sends the data to Home Assistant.", "tags": ['precision']},
    {"term": "AppDaemon", "defn": "AppDaemon is the Python software environment that operates the primary decision loop of Crop Steering, which has approximately 5900 lines, on Home Assistant.", "tags": ['precision']},
    {"term": "Manual override", "defn": "A manual override is a total lockout for each zone. When it is ON, the zone gets no water. The lockout stops automatic irrigation, emergency irrigation and a manual trigger.", "tags": ['precision']},
    {"term": "EC ratio", "defn": "The EC ratio is the measured EC divided by the target EC. When the ratio is more than 1, the salt strength is too high (apply more water to dilute). When the ratio is less than 1, the salt strength is too weak (apply less water).", "tags": ['precision']},
    {"term": "Phase (P0-P3)", "defn": "The phase of a row is its position in the cycle of each day. P0 is the morning dryback, P1 is the ramp-up, P2 is the maintenance, and P3 is the time before lights-off and the night.", "tags": ['precision']},
    {"term": "Zone / row", "defn": "A zone (row) is one of the 3 sections of the room that you control independently. Each section has a pair of probes and a valve. All sections get feed from the same tank.", "tags": ['precision']},
    {"term": "Vegetative / Generative mode", "defn": "The vegetative mode and the generative mode are the two steering modes. They select the dryback targets and the EC targets that the engine uses. The vegetative mode keeps the plant wet and in bulking, and the generative mode causes stress and flowering.", "tags": ['precision']},
    {"term": "System enabled vs Auto irrigation", "defn": "System enabled is the primary arm/kill switch. When it is OFF, no shot occurs. Auto irrigation only stops the automatic shots, and you can apply manual shots.", "tags": ['precision']},
    {"term": "pH/EC gate", "defn": "The pH/EC gate is a safety check. It stops irrigation when the pH or the EC of the source tank is out of the limits that you set (default pH 5.8-6.2). It also sends an alert to your mobile device, with the alternative 'Irrigate Anyway'.", "tags": ['precision']},
    {"term": "Blocked-dripper guard", "defn": "The blocked-dripper guard is a fail-safe. It stops the irrigation of a row for approximately 2 hours after too many emergency shots fail (default 4 in 30 min). Each row has an on/off switch for it.", "tags": ['precision']},
    {"term": "Fail-safe read", "defn": "In a fail-safe read, the engine cannot find the condition of the primary arm switch. The engine then uses the condition OFF and does not apply a shot. Thus a condition that is not synchronized cannot cause the engine to operate without data.", "tags": ['precision']},
    {"term": "AppDaemon engine", "defn": "The AppDaemon engine is the automatic controller (file master_crop_steering_app.py). It reads the sensors and the settings, selects the phase of each row, and operates the hardware sequence.", "tags": ['precision']},
    {"term": "Vegetative vs generative", "defn": "The two steering targets are the vegetative target and the generative target. The vegetative target increases the growth of roots and leaves (longer drybacks, lower EC). The generative target increases flowering and fruit (shorter drybacks, higher EC).", "tags": ['precision']},
    {"term": "Solenoid valve", "defn": "A solenoid valve is an electrically operated valve. It opens or closes the flow of water when the relay board operates it.", "tags": ['precision']},
    {"term": "Home Assistant", "defn": "Home Assistant is open-source software, with no cost, for home automation. It operates the dashboards, automations and integrations that are in this paper.", "tags": ['precision']},
    {"term": "Runoff", "defn": "Runoff is the nutrient water that is more than the pot can hold. It flows out of the bottom of the pot during or after irrigation.", "tags": ['precision']},
    {"term": "Cleanroom grade (CNC, D, C, B, A)", "defn": "A cleanroom grade shows how clean the air of a room is. In CNC, the air has no control, and no other grade has air as clean as Grade A. The grades agree with the ISO 14644 classes (D=ISO 8, C=ISO 7, A=ISO 5).", "tags": ['reference']},
    {"term": "ISO 14644", "defn": "ISO 14644 is the international standard that gives classes of cleanrooms. A class is the maximum permitted number of airborne particles in each cubic meter.", "tags": ['reference']},
    {"term": "Pressure cascade", "defn": "A pressure cascade is a sequence of air pressures that you set. A clean room has a higher pressure than the next room that is less clean. Thus air always flows from the clean room to the room that is less clean, and contamination cannot move to the product.", "tags": ['reference']},
    {"term": "Airlock / gowning cascade", "defn": "An airlock (gowning cascade) is a sealed room between two spaces. Its doors cannot open at the same time. Personnel put on more protective clothing in the room before they go into a space with a higher grade.", "tags": ['reference']},
    {"term": "C1D1", "defn": "C1D1 (Class 1 Division 1) is a classification for areas where flammable solvent vapor can be in the air. It is for electrical equipment and rooms. These areas must have explosion-proof equipment and gas detection.", "tags": ['reference']},
    {"term": "Residual solvent", "defn": "Residual solvent is the remaining solvent (for example butane and ethanol) in a completed extract. It is a primary safety test, with specified maximum limits in ppm.", "tags": ['reference']},
    {"term": "Water activity (Aw)", "defn": "Water activity (Aw) shows the quantity of free water that is available to microbes, as a value from 0 to 1. An Aw of <=0.55–0.65 prevents the growth of mold and yeast.", "tags": ['reference']},
    {"term": "CCP (Critical Control Point)", "defn": "A CCP (Critical Control Point) is a step in an operation, with a measured limit that prevents a specified hazard. It is a term from HACCP for control during the operation.", "tags": ['reference']},
    {"term": "Batch / lot", "defn": "A batch (lot) is one specified production run with one ID. The ID stays with the material in each transfer.", "tags": ['reference']},
    {"term": "Genealogy / traceability", "defn": "Genealogy (traceability) is the record that connects each completed unit to its source lots, operators, equipment and conditions, forward and back. It makes possible a recall of specified lots only.", "tags": ['reference']},
    {"term": "Quarantine / Released / Rejected", "defn": "Quarantine, Released and Rejected are the three statuses of material. Material can have only one of the three statuses. The status of the material and the status in the system must always agree.", "tags": ['reference']},
    {"term": "Deviation", "defn": "A deviation is each difference from the approved procedure in the documents. You must record it and do an investigation.", "tags": ['reference']},
    {"term": "OOS (Out Of Specification)", "defn": "An OOS (Out Of Specification) is a test result that is out of the accepted limit. It starts an investigation before the decision to release.", "tags": ['reference']},
    {"term": "QA / release", "defn": "QA (Quality Assurance) is the unit (not production) that makes the decision, with a signature, to release a batch to the market.", "tags": ['reference']},
    {"term": "CoA (Certificate of Analysis)", "defn": "A CoA (Certificate of Analysis) is the document that gives a list of the test results of a batch and compares them with the specification. You supply it at release.", "tags": ['reference']},
    {"term": "ALCOA+", "defn": "ALCOA+ is a list of properties for data integrity. Records must be Attributable, Legible, Contemporaneous, Original and Accurate, plus Complete, Consistent, Enduring and Available.", "tags": ['reference']},
    {"term": "V-model (DQ/IQ/OQ/PQ)", "defn": "The V-model is a qualification system for equipment. It connects each design stage to a check that agrees with that stage (Design, Installation, Operational and Performance Qualification).", "tags": ['reference']},
    {"term": "MACO", "defn": "MACO (Maximum Allowable Carryover) is the residue limit that you calculate. You use it as the acceptance criterion in cleaning validation.", "tags": ['reference']},
    {"term": "EM (Environmental Monitoring)", "defn": "EM (Environmental Monitoring) is the procedure to get samples of non-viable particles, viable air, surfaces and personnel. You compare the results with the alert limits and the action limits.", "tags": ['reference']},
    {"term": "GACP", "defn": "GACP (Good Agricultural and Collection Practice) is the standard for cultivation and drying, before the GMP facility. It supplies biomass that agrees with GMP to the facility.", "tags": ['reference']},
    {"term": "3D model", "defn": "A 3D model is an image of the building on a screen. You can turn it, change its size and select parts of it. The software makes it from the floor plan, and it is not a photo or render that does not change.", "tags": ['precision']},
    {"term": "Three.js", "defn": "Three.js is a code library with no cost that many persons use. It shows 3D scenes that you can control, in a usual web browser. You do not install software.", "tags": ['precision']},
    {"term": "Floor plan", "defn": "A floor plan is a flat drawing from an architect. It shows the walls, doors and rooms from above, usually with dimensions in millimeters.", "tags": ['precision']},
    {"term": "Render", "defn": "To render is to show the 3D scene as an image on the screen. The software does this many times each second. Thus you can control the scene.", "tags": ['precision']},
    {"term": "Scene", "defn": "The scene is all the objects in the 3D model: slabs, walls, benches, lights and cameras. The model holds them together in one structure.", "tags": ['precision']},
    {"term": "JSON / data file", "defn": "A JSON file (data file) is a list of facts that a person can read (room names, sizes and positions). The code reads it to make the model.", "tags": ['precision']},
    {"term": "Schema", "defn": "The schema is the agreed structure of the data file. Here it has only four types of record: rooms, walls, equipment and devices.", "tags": ['precision']},
    {"term": "Extrude", "defn": "To extrude is to extend a flat 2D shape (for example, the shape of a floor) up, to give it thickness or height.", "tags": ['precision']},
    {"term": "Opening", "defn": "An opening is a gap in a wall, for example a door, a pass-through or a roller door. The data give its position along the wall, its width and its top (head) height.", "tags": ['precision']},
    {"term": "Fit-out", "defn": "The fit-out is the equipment and furniture in the bare shell of the building: benches, lights, dehumidifiers, tanks and racks.", "tags": ['precision']},
    {"term": "Instancing", "defn": "Instancing is the method to show many objects that are the same, for example 210 plants, in one batch and not one at a time. It is the primary method to keep the model fast.", "tags": ['precision']},
    {"term": "FOV cone", "defn": "An FOV cone is a transparent shape that shows the area in the field of view of a camera. The floor out of all the cones is a possible blind spot.", "tags": ['precision']},
    {"term": "Raycasting / picking", "defn": "Raycasting (picking) is the method to find which 3D object you select with the mouse. The software sends a ray that you cannot see from the cursor into the scene.", "tags": ['precision']},
    {"term": "PTZ camera", "defn": "A PTZ camera is a pan-tilt-zoom camera. It can turn and zoom to monitor a movement. Here it is for coverage of intrusion on the roof.", "tags": ['precision']},
    {"term": "glTF", "defn": "glTF is a standard 3D file format. You use it to import models with much detail, which you make in tools (for example Blender), and to export the building.", "tags": ['precision']},
    {"term": "Digital twin", "defn": "A digital twin is a 3D model connected to the data of sensors in the facility. Thus it shows the temperature, the humidity and the equipment status at this time.", "tags": ['precision']},
    {"term": "Draw call", "defn": "A draw call is one instruction to the graphics card to show an object. When the number of draw calls is smaller, the model is faster (keep the number less than approximately 300).", "tags": ['precision']},
    {"term": "Tone mapping", "defn": "Tone mapping is the step that changes the light intensity of the scene into an image that looks correct. With ACES tone mapping, surfaces of pure white become too bright and show no detail. Thus use a warm off-white.", "tags": ['precision']},
    {"term": "GACP (Good Agricultural and Collection Practice)", "defn": "GACP (Good Agricultural and Collection Practice) is the standard for the cultivation and collection of the starting material of medicinal cannabis. In this standard, the material is a plant crop before it becomes a medicine.", "tags": ['reference']},
    {"term": "QMS / PQS (Quality Management System / Pharmaceutical Quality System)", "defn": "A QMS (Quality Management System) or PQS (Pharmaceutical Quality System) is the group of responsibilities, procedures, operations and resources with which an organization controls quality. The manual uses the two names for the same system.", "tags": ['reference']},
    {"term": "Quality Manual", "defn": "The Quality Manual is the top document of the quality system. It gives general information about the quality system, and it refers to the procedures and records below it.", "tags": ['reference']},
    {"term": "GDP (Good Documentation Practice)", "defn": "GDP (Good Documentation Practice) is a group of procedures to make and to correct records. You make a record at the time of the task, and you cannot erase it. A correction is one line through the error, with initials, a date and a cause, and the initial entry stays easy to read.", "tags": ['reference']},
    {"term": "CAPA (Corrective and Preventive Action)", "defn": "CAPA (Corrective and Preventive Action) is a procedure that starts from the root cause. Corrective action repairs a problem that occurred. Preventive action makes sure that a problem does not occur, or does not occur again.", "tags": ['reference']},
    {"term": "Change Control", "defn": "The standard procedure for each change that can change the quality of the product or the validated state is change control. In this procedure, you examine the change, give approval for it and then make it.", "tags": ['reference']},
    {"term": "QRM (Quality Risk Management)", "defn": "QRM (Quality Risk Management) is a method for decisions on risk, as in ICH Q9. You use it to find, examine and control risks in the system. You also do a review of the risks and give information about the risks.", "tags": ['reference']},
    {"term": "QA / QC (Quality Assurance / Quality Control)", "defn": "QA (Quality Assurance) sets the quality system, monitors it, and makes release decisions independently of production. QC (Quality Control) does the sampling and the testing.", "tags": ['reference']},
    {"term": "RP (Responsible Person)", "defn": "An RP (Responsible Person) is the person who has the legal responsibility for the tasks in the regulations. The RP monitors these tasks, gives approval to release a batch, gives approval for recalls, and is the person that the regulator contacts.", "tags": ['reference']},
    {"term": "PIC/S PE009", "defn": "PIC/S PE009 is the Guide to GMP for Medicinal Products of the Pharmaceutical Inspection Co-operation Scheme. It is the reference standard, and the manual has a structure that agrees with it.", "tags": ['reference']},
    {"term": "ICH Q9 / Q10", "defn": "ICH Q9 and ICH Q10 are international harmonization guidelines. Q9 is for Quality Risk Management and Q10 is for the Pharmaceutical Quality System.", "tags": ['reference']},
    {"term": "Annex 11 / PI 041", "defn": "Annex 11 and PI 041 give the GMP requirements for computerized systems and data integrity (access control, audit trails, validation and backups).", "tags": ['reference']},
    {"term": "Batch / Lot Record", "defn": "A batch (lot) record is the document that records all the materials, tasks, personnel, equipment, results and disposition for one batch (FRM-MF-004). REG-CU-001 holds these records together.", "tags": ['reference']},
    {"term": "Validation / Qualification", "defn": "Validation (qualification) is the evidence, in documents, that facilities, equipment, utilities and operations do their specified tasks.", "tags": ['reference']},
    {"term": "Register", "defn": "A register is one controlled document that gives an index of records of one type (for example deviations, CAPAs, documents). It becomes larger only when you add rows.", "tags": ['reference']},
    {"term": "Master Document Register (REG-QM-001)", "defn": "The Master Document Register (REG-QM-001) is the primary index. It gives a list of all the controlled documents, each with its version at this time, its document owner and its review status.", "tags": ['reference']},
    {"term": "Management Review", "defn": "Management review is the review of the performance and the effectiveness of the quality system, by senior management. The review occurs at regular intervals, a minimum of one time each year.", "tags": ['reference']},
    {"term": "MQS (Minimum Quality Standard)", "defn": "The MQS (Minimum Quality Standard) is the quality standard for products of medicinal cannabis in the NZ Misuse of Drugs (Medicinal Cannabis) Regulations 2019.", "tags": ['reference']},
]
